import React from 'react';
import { useNavigate } from 'react-router-dom';

const FEATURES = [
  { icon: '🎲', title: 'Mystery Box', sub: 'Surprise me within my budget!', path: '/mystery-box', color: 'orange-500' },
  { icon: '♻️', title: 'Zero-Waste Flash Sales', sub: 'Grab great food at 50–70% off', path: '/flash-sales', color: 'green-500' },
  { icon: '⚖️', title: 'Reverse Bid', sub: 'Name your price, restaurants compete', path: '/reverse-bid', color: 'purple-500' },
  { icon: '👩‍🍳', title: 'Home Chef', sub: 'Authentic homemade food nearby', path: '/home-chef', color: 'yellow-500' },
  { icon: '🔮', title: 'Predictive Orders', sub: 'Zero-click predictive orders based on habits', path: '/routine-builder', color: 'blue-500' },
];

export default function ExplorePage() {
  const navigate = useNavigate();

  return (
    <div className="min-h-screen bg-gray-900 pt-16 px-6 sm:px-10">
      <div className="max-w-2xl mx-auto">
        <h1 className="text-3xl font-extrabold text-white mb-2">Explore ✨</h1>
        <p className="text-sm text-gray-400 mb-8">New ways to discover & order food</p>

        <div className="space-y-4">
          {FEATURES.map((f, i) => (
            <button
              key={i}
              onClick={() => navigate(f.path)}
              className="w-full bg-[#1e1e1e] hover:bg-gray-800 transition rounded-2xl p-6 flex items-center shadow-lg text-left"
            >
              <div className={`w-14 h-14 rounded-full flex items-center justify-center mr-5 shrink-0 bg-${f.color}/10 border border-${f.color}/20`}>
                <span className="text-3xl">{f.icon}</span>
              </div>
              <div className="flex-1 pr-4">
                <h3 className="text-lg font-extrabold text-white">{f.title}</h3>
                <p className="text-sm text-gray-400 mt-1 leading-relaxed">{f.sub}</p>
              </div>
              <span className={`text-${f.color} font-extrabold text-3xl`}>›</span>
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}
